Object.assign(ARTICLES, {"uswa-flair-steals-debut-0720": {"p": "uswa", "kicker": "USWA · Championship TV Special · Dallas Sportatorium, July 20", "title": "The Nature Boy Steals One in Dallas", "dek": "Ric Flair rolls up Terry Funk with a handful of tights in his USWA debut, and the Texas Outlaws chase him out of the building.", "by": "By the magazine staff", "date": "1991-07-20", "factTitle": "The Card", "facts": [["Main", "Ric Flair d. Terry Funk"], ["Match of the night", "Santo, Volador & Dragón d. Black Magic, Pierroth & Zakowski"], ["Crowd", "4,500 (sellout)"]], "body": [["h", "The Nature Boy Steals One in Dallas"], ["p", "Ric Flair came to the Sportatorium on Saturday night for his first match in the USWA, and he left with a win that Dallas will be arguing about for weeks. Terry Funk had Chris Adams and Kevin Von Erich in his corner, and for twenty-two minutes he gave Flair everything the Texas Outlaws had promised. Then Kevin climbed onto the apron to have words with the referee. With the official's back turned, Flair rolled Funk up, grabbed a handful of tights, and held on. The hand came down three times at 22:03. Funk was on his feet before the bell stopped ringing, and all three Outlaws chased Flair up the aisle and out of the building."], ["h", "Santo, Volador and Dragon Steal the Show"], ["p", "Six days before they meet the Guerreros for the first CMLL World Trios Championship in Mexico City, El Hijo del Santo, Volador and Ultimo Dragon gave Dallas the match of the night. They beat Black Magic, Pierroth Jr. and Rob Zakowski in two straight falls. Santo took the first with a spinning backbreaker on Pierroth at 10:12, and Dragon ended it at 15:10 with a moonsault on Zakowski. The Sportatorium was on its feet for all six men at the end. If this was their warmup for the trios final, the Guerreros have reason to worry."], ["h", "Houston Gets His Invitation"], ["p", "For weeks Scotty Flamingo has told Sam Houston he wasn't good enough for the Flamingo Invitational. On Saturday, in front of his home-state crowd, Houston finally got his invitation, and Flamingo found out otherwise. Houston hit the running bulldog at 11:07 and pinned him clean. After three straight wins, it's the first loss of the Invitational for Flamingo."], ["h", "The Outlaws Ride"], ["p", "One week ago in Louisville, the Nightmares beat Eric Embry and Tom Prichard. For the rematch, Embry and Prichard brought Kevin Von Erich, and the Nightmares brought a surprise of their own. Their third man was Dennis Condrey, a rulebreaker who has never been on the side of the fans in his life. Danny Davis and Ken Wayne needed help, and they took it from the last place anyone expected. It wasn't enough. Kevin locked the claw on Wayne, and Wayne gave up at 13:16."], ["h", "Studd and Brickhouse Top the Gilberts"], ["p", "Diamond Studd and Brickhouse Brown beat Doug and Eddie Gilbert at 12:07, when Brickhouse flattened Doug with a running lariat. Eddie didn't stick around to help his brother up. He was through the curtain before Doug got off the mat. One week from tonight in Nashville, Brickhouse gets his shot at Steve Austin's Southern Heavyweight Championship, and he goes in with the momentum. Hot Stuff International looks like it is coming apart."], ["h", "Spivey Crashes the Tag Team Brawl"], ["p", "Calculated Force and the Memphis Mafia picked up right where they left off in Louisville. Scott Steiner, Tully Blanchard, Dirty White Boy and Rex King were fighting on the floor when Dan Spivey came through the crowd alone. Stan Hansen is in Japan, and Spivey made it clear he didn't need him. He powerbombed Steiner on the concrete, then did the same to Rex King. Nobody made it back into the ring, and the referee counted out all four men at 11:20. Spivey stood over the wreckage and told the champions the dog collar rematch is still coming, with or without his partner. Watching it all from the entrance was Paul Ellering."], ["h", "Jamie Dundee Brings the Chain"], ["p", "No countout, no disqualification, and Jamie Dundee took full advantage. Two weeks after he attacked Jimmy Valiant backstage in Memphis with a chain, he had another one handed to him at ringside, and the man doing the handing was Paul Ellering. One punch with the chain wrapped around Jamie's fist at 10:24, and Valiant was finished. Ellering was at ringside for one match and at the entrance for another. That is twice in one night."], ["h", "Kerry and Bret, One More Time"], ["p", "Eddie Marlin opened the show with the announcement Texas wanted to hear: Kerry Von Erich and Bret Hart will meet again for the Unified World Championship, in a 60-minute Iron Man match at Reunion Arena. Then Kerry and Bret met face to face in the ring, and neither man gave an inch. First, Bret defends the title against Jeff Jarrett next Saturday in Nashville."], ["p", "NEXT: Evansville, Wednesday, July 24. The Moondogs against Mark Canterbury and Robert Fuller."]]}, "uswa-observer-dallas-0720": {"p": "uswa", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-20", "region": "Memphis Report", "kicker": "USWA · Dallas Sportatorium, July 20", "title": "The Sportatorium Sells Out", "dek": "Flair's debut draws a sellout and the best merchandise number of the summer, the lucha trios steals the show, and Ellering looks like he's building a stable.", "factTitle": "Match observations", "facts": [["Venue", "Dallas Sportatorium"], ["City", "Dallas, TX"], ["Date", "July 20, 1991"], ["Attendance", "4,500 (sellout)"], ["Average ticket", "$11.00"], ["Gate", "$49,500"], ["Merchandise", "$13,500"], ["Card", "***1/4"], ["Match of the night", "Lucha trios, ****1/2"]], "body": [["p", "The USWA sold out the Sportatorium on Saturday for Ric Flair's first match with the company, 4,500 at $11 a head for $49,500. That's the first USWA sellout this month outside of the Mid-South Coliseum and the third biggest gate of July, behind Star Wars and the Memphis TV show on 7/6. Merchandise did $13,500, which is $3 a head and by far the best per-head number the company has done this summer. Memphis on 7/6 did $2,000 with the same size crowd. Dallas fans came to see Flair, and they came to see the Von Erichs, and they spent money on both. July is now at $314,520 in gates with three shows left. The card came in at ***1/4. Nobody was hurt."], ["p", "Flair pinned Terry Funk in 22:03, ***1/4. It was good, not great, and it was built for the finish rather than the workrate. Kevin Von Erich got on the apron to argue with the referee, and Flair rolled Funk up with a handful of tights. The Outlaws chased him out of the building. It's the right way to do it. Flair gets a win in his first match, Funk loses nothing, and every Texan in that building wants to see Flair get his. The question is where it goes next. Flair has no USWA date announced, and the Texas Outlaws now have a grudge with no match attached to it. With five Outlaws and one Flair, he's going to need friends, and the guess here is that he finds them among the people Texas already hates."], ["p", "The match of the night, and the best match on a USWA card since Star Wars, was the lucha trios. El Hijo del Santo, Volador and Ultimo Dragon beat Black Magic, Pierroth Jr. and Rob Zakowski in two straight falls, ****1/2, 15:10. Santo pinned Pierroth with a spinning backbreaker and Dragon finished Zakowski with a moonsault. All six worked Arena Mexico on Friday night, and Santo, Volador and Dragon went almost forty minutes in the Tercias semifinal there before getting on a plane. They still had the best match on the show. The Sportatorium crowd had no reason to know who Volador or Dragon were, and by the second fall they were standing. The three of them face the Guerreros for the first CMLL World Trios titles next Friday at Verano de Escandalo, so this was the last time anyone in the States sees them before that."], ["p", "Sam Houston pinned Scotty Flamingo with the bulldog in 11:07, **3/4. That ends Flamingo's run in his own Invitational at three, and Houston got it in his home state, which was the whole point of putting it here. The match was fine. The interesting part is what it does to Flamingo. He's been the best talker on the undercard for a month, and the Invitational was built to get him over as a cocky heel who keeps getting away with it. He just didn't get away with it. It's either the end of the gimmick or the start of a rematch, and the office hasn't said which."], ["p", "Dan Spivey came through the crowd alone and powerbombed Scott Steiner and Rex King on the floor during Calculated Force against the Memphis Mafia. All four were counted out at 11:20. **1/4. Stan Hansen is in Japan with All Japan this week, and Spivey told the champions the dog collar rematch is still on with or without him. The bigger story was Paul Ellering, who watched the whole thing from the entrance. Ellering was at ringside earlier in the night and handed Jamie Dundee the chain he used on Jimmy Valiant. Ellering has Andre the Giant, he has Jamie, and now he's showing up wherever Hansen and Spivey are. Nobody in the office will say it, but it looks like he is building a stable. Calculated Force and the Mafia are still unresolved after two meetings, and neither match has been much good."], ["p", "Jamie Dundee pinned Jimmy Valiant in 10:24 in a no countout, no DQ match, ***. Ellering handed Jamie a chain at ringside, and one punch ended it. Valiant is still one of the most popular babyfaces the company has, and this was a good use of him. Jamie is being built into somebody, fast. Bill Dundee holds the TV title, and Jamie's last name makes that story write itself."], ["p", "Diamond Studd and Brickhouse Brown beat Doug and Eddie Gilbert in 12:07, ***, when Brickhouse hit Doug with the running lariat. Eddie walked out before Doug got off the mat. Hot Stuff International is coming apart in public. Austin and Eddie have been arguing for two weeks, Missy has been working both sides, and now Eddie has left his own brother lying in the ring. Brickhouse gets Austin for the Southern title in Nashville next Saturday, and beating a Gilbert clean was the right way to send him in."], ["p", "Kevin Von Erich, Eric Embry and Tom Prichard beat the Nightmares and Dennis Condrey in 13:16, **1/2, when Kevin made Ken Wayne submit to the claw. The surprise was Condrey, who has been a heel his entire career, coming out as the third man for the babyface Nightmares. The crowd didn't know whether to cheer him or not, and frankly neither did the Nightmares. It got the Texas Bunch back the loss from Louisville, and it put Kevin in a winning six-man on the night his brother's Iron Man match was announced. Condrey is worth watching. Either he turned, or the Nightmares just made a mistake."], ["p", "Eddie Marlin opened the show by announcing Kerry Von Erich against Bret Hart for the Unified World title, a sixty-minute Iron Man match at the Reunion Arena. That would be the USWA's first show in Dallas's biggest building, which holds more than 17,000, and it's the right match for it. Bret and Kerry then went face to face. Bret said Kerry stole the pin in Louisville; Kerry told him he was standing in his daddy's house. It was good, simple stuff, and they stayed off each other, which leaves the first contact for later. Bret defends against Jeff Jarrett in Nashville next Saturday."], ["p", "The Sportatorium experiment worked. The building sold out, the merchandise number was the best of the summer, and the company has a Reunion Arena main event to sell on top of it. The question going forward is whether Dallas becomes a regular stop or a special event, and with Kerry, Kevin, Funk and now Flair all living there, it should be regular."], ["p", "1. Eddie Marlin announced Kerry Von Erich vs. Bret Hart, Unified World title, 60-minute Iron Man, at the Reunion Arena."], ["p", "2. Kerry Von Erich and Bret Hart face to face. No contact."], ["p", "3. No countout, no DQ: Jamie Dundee pinned Jimmy Valiant in 10:24 after a chain shot. Paul Ellering handed Jamie the chain. ***"], ["p", "4. Kevin Von Erich, Eric Embry & Tom Prichard beat the Nightmares & Dennis Condrey when Kevin made Ken Wayne submit to the claw in 13:16. **1/2"], ["p", "5. Calculated Force vs. Memphis Mafia went to a double countout at 11:20 after Dan Spivey powerbombed Steiner and Rex King on the floor. Ellering watched from the entrance. **1/4"], ["p", "6. Diamond Studd & Brickhouse Brown beat Doug & Eddie Gilbert when Brickhouse pinned Doug with a running lariat in 12:07. Eddie walked out on Doug. ***"], ["p", "7. Two out of three falls: El Hijo del Santo, Volador & Ultimo Dragon beat Black Magic, Pierroth Jr. & Rob Zakowski 2-0. Santo pinned Pierroth with a spinning backbreaker (10:12); Dragon pinned Zakowski with a moonsault (15:10). ****1/2"], ["p", "8. Flamingo Invitational #4: Sam Houston pinned Scotty Flamingo with a running bulldog in 11:07. Flamingo's first loss in the Invitational. **3/4"], ["p", "9. Ric Flair pinned Terry Funk with a roll-up, holding the tights, in 22:03, after Kevin Von Erich distracted the referee. Flair's USWA debut. ***1/4"], ["p", "Overall card: ***1/4"], ["p", "Next is Evansville on Wednesday: the Moondogs against Mark Canterbury and Robert Fuller."]]}, "uswa-diary-santo-0720": {"p": "uswa", "series": "diary", "by": "El Hijo del Santo", "date": "1991-07-20", "place": "Hotel by the highway, Dallas", "kicker": "From the Road · Dallas, July 20", "title": "A Barn With a Ring in the Middle", "dek": "El Hijo del Santo on a morning flight from Mexico City, a tin building in Dallas, and Ric Flair from the curtain.", "factTitle": "The Night", "facts": [["Show", "Championship TV Special"], ["Match", "Lucha trios, 2 out of 3 falls"], ["Finish", "Dragón's moonsault, 15:10"], ["Rating", "****1/2"], ["Next", "Verano de Escándalo, 7/26"]], "body": [["p", "Last night at this time I was lying on the floor of the dressing room in Arena Mexico, after almost forty minutes with Los Brazos, and I could not feel my legs. Tonight I am in a hotel next to the highway in Dallas, Texas, and I can feel all of them, every one of those forty minutes."], ["p", "We left Mexico City in the morning. Volador slept the whole flight. Dragon read a Japanese newspaper that he had carried since Acapulco, the same one, three days old. Black Magic, Pierroth and Rob Zakowski were on the same plane, and we ate breakfast at the same table at the airport, because in an airport nobody is a rudo and nobody is a tecnico. Tonight they were again. Zakowski worked in Arena Mexico on Friday too. He is a big, quiet man, and he works hard for somebody who does not understand a word of what the referee tells him in Mexico."], ["p", "My father told me about the Sportatorium. He said it was a barn with a ring in the middle and the loudest people in America. He was right about both. It is made of tin, and it is hot like Arena Coliseo in August. When the people stamp their feet you feel it in the ring before you hear it."], ["p", "In Memphis on July 1, the people did not know me. Tonight in Dallas they did not know Volador or Dragon either. That is fine. They learn quickly here. By the end of the first fall they were cheering for the mask, and when Dragon came off the top with the moonsault to finish Zakowski, all of them were standing. Pierroth told me in the dressing room afterward that it was the best crowd he has worked for this year. Pierroth does not give compliments, not to rudos and not to tecnicos."], ["p", "I took the first fall with the backbreaker on Pierroth. I was a little slow getting him up. My back has not forgiven me for last night yet."], ["p", "After our match I watched the main event from the curtain. Ric Flair. In Mexico we see his matches on tape, years after. To see him in person is different. He does nothing fast, and everything he does is for the people in the last row. He beat Terry Funk with a roll-up, his hand full of the tights, and the building wanted to kill him. Then the Von Erich brother and his friends chased him all the way to the parking lot. In Mexico that would have been a riot. Here they only threw cups."], ["p", "Next Friday is the most important match of my career so far. The Guerreros, in Arena Mexico, for the first trios belts. Eddie and I have shared dressing rooms in two countries this summer. Next week we share a ring, and only one of us goes home with a belt."], ["p", "The plane is in the morning. Ice on the back, and sleep."]]}});
BANNER_SVG.uswa = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 1440 360\" role=\"img\" aria-label=\"USWA. United States Wrestling Association. Memphis, Tennessee. Mid-South Coliseum and Dallas Sportatorium.\" style=\"display:block;width:100%;height:auto;background:#0E0E0E\"><rect width=\"1440\" height=\"360\" fill=\"#0E0E0E\"/><rect width=\"1440\" height=\"10\" fill=\"#1E3A6E\"/><rect y=\"350\" width=\"1440\" height=\"10\" fill=\"#1E3A6E\"/><rect y=\"10\" width=\"1440\" height=\"3\" fill=\"#C8283A\"/><rect y=\"347\" width=\"1440\" height=\"3\" fill=\"#C8283A\"/><rect y=\"118\" width=\"1440\" height=\"4\" fill=\"#232323\"/><rect y=\"178\" width=\"1440\" height=\"4\" fill=\"#232323\"/><rect y=\"238\" width=\"1440\" height=\"4\" fill=\"#232323\"/><image href=\"data:image/webp;base64,\" x=\"40.0\" y=\"102.7\" width=\"480.0\" height=\"154.7\"/><g><text x=\"560\" y=\"84\" font-family=\"Oswald,'Roboto Condensed','Arial Narrow',sans-serif\" font-weight=\"600\" font-size=\"20\" letter-spacing=\"7\" fill=\"#A8A8A8\">MEMPHIS, TENNESSEE</text><text x=\"560\" y=\"190\" font-family=\"Anton,Impact,'Arial Narrow',sans-serif\" font-size=\"100\" letter-spacing=\"2\" fill=\"#FFFFFF\">UNITED STATES</text><text x=\"560\" y=\"258\" font-family=\"Anton,Impact,'Arial Narrow',sans-serif\" font-size=\"54\" letter-spacing=\"5\" fill=\"#C8283A\">WRESTLING ASSOCIATION</text><g transform=\"translate(560 278)\"><polygon points=\"12,2 15.09,8.26 22,9.27 17,14.14 18.18,21.02 12,17.77 5.82,21.02 7,14.14 2,9.27 8.91,8.26\" fill=\"#C8283A\"/></g><g transform=\"translate(592 278)\"><polygon points=\"12,2 15.09,8.26 22,9.27 17,14.14 18.18,21.02 12,17.77 5.82,21.02 7,14.14 2,9.27 8.91,8.26\" fill=\"#C8283A\"/></g><g transform=\"translate(624 278)\"><polygon points=\"12,2 15.09,8.26 22,9.27 17,14.14 18.18,21.02 12,17.77 5.82,21.02 7,14.14 2,9.27 8.91,8.26\" fill=\"#C8283A\"/></g><text x=\"672\" y=\"298\" font-family=\"Oswald,'Roboto Condensed','Arial Narrow',sans-serif\" font-weight=\"500\" font-size=\"20\" letter-spacing=\"5\" fill=\"#D4D4D4\">MID-SOUTH COLISEUM · DALLAS SPORTATORIUM</text></g><text x=\"1400\" y=\"330\" text-anchor=\"end\" font-family=\"Oswald,'Roboto Condensed','Arial Narrow',sans-serif\" font-weight=\"500\" font-size=\"14\" letter-spacing=\"4\" fill=\"#8C8C8C\">TNM WORLD WRESTLING REPORT</text></svg>";
