Object.assign(ARTICLES, {"uswa-iron-man-reunion-0720": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-20", "region": "Memphis Report", "kicker": "USWA · Dallas Sportatorium, July 20", "title": "Iron Man at the Reunion", "dek": "Kerry Von Erich vs. Bret Hart II is set: 60 minutes, Iron Man rules, for the Unified World Title.", "body": [["p", "Eddie Marlin opened the Championship TV Special in Dallas with the announcement Texas has been waiting for: Kerry Von Erich vs. Bret Hart II for the Unified World Title, 60 minutes, Iron Man rules, at the Reunion Arena. Kerry and Bret went face to face in the ring afterward and never touched each other."], ["p", "Bret has to get there first. He defends against Jeff Jarrett in Nashville on July 27. The date for the Reunion Arena is To establish."]], "facts": [["Match", "Kerry Von Erich vs. Bret Hart II"], ["Title", "USWA Unified World"], ["Rules", "60 minutes, Iron Man"], ["Where", "Reunion Arena, Dallas"], ["First", "Bret vs. Jarrett, Nashville, July 27"]], "factTitle": "The Match"}, "uswa-houston-invitational-0720": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-20", "region": "Memphis Report", "kicker": "USWA · Dallas Sportatorium, July 20", "title": "Houston Crashes the Invitational", "dek": "Scotty Flamingo was 3–0 in his own Invitational. Sam Houston beat him with the bulldog.", "body": [["p", "Scotty Flamingo built the Flamingo Invitational to show off, and for three weeks it worked. He beat Scott Taylor with a low blow in Louisville and Jim Powers with his feet on the ropes in Jonesboro. In Dallas, Sam Houston caught him with the running bulldog at 11:07 (**3/4)."], ["p", "That's Flamingo's first Invitational loss. Houston has been a different man since he came back in July, and he did it in Dallas."]], "facts": [["#2", "Flamingo d. Scott Taylor (low blow)"], ["#3", "Flamingo d. Jim Powers (feet on the ropes)"], ["#4", "Sam Houston d. Flamingo, bulldog, 11:07"], ["Rating", "**3/4"], ["Flamingo", "first Invitational loss"]], "factTitle": "The Invitational"}, "uswa-ellering-plans-0720": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-20", "region": "Memphis Report", "kicker": "USWA · Dallas Sportatorium, July 20", "title": "Ellering's Plans", "dek": "Paul Ellering handed Jamie Dundee a chain, then watched Dan Spivey powerbomb two men on the floor.", "body": [["p", "Paul Ellering was everywhere in Dallas without wrestling a minute. He handed Jamie Dundee the chain that beat Jimmy Valiant in a no-countout, no-DQ match in 10:24. Later, Calculated Force and the Memphis Mafia went to a double countout, and Ellering watched from the entrance as Dan Spivey powerbombed Scott Steiner and Rex King on the floor."], ["p", "Spivey says the dog collar rematch is coming, with or without Stan Hansen, who is working All Japan's Summer Action Series. What Ellering is building is To establish."]], "facts": [["Dundee", "d. Jimmy Valiant (chain), 10:24"], ["Chain", "from Ellering"], ["Spivey", "powerbombed Steiner and King on the floor"], ["Next", "dog collar rematch"], ["Hansen", "in Japan with All Japan"]], "factTitle": "The Night"}, "uswa-canterbury-bleeds-0717": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-17", "region": "Memphis Report", "kicker": "USWA · Earl Bell Community Center, Jonesboro, July 17", "title": "Canterbury Bleeds", "dek": "Mark Canterbury beat Spot by DQ, and the Honky Tonk Man and the Moondogs busted him open for it.", "body": [["p", "Mark Canterbury beat Moondog Spot by disqualification in 13:59 when the Honky Tonk Man interfered, and that was the end of the good news. Honky and the Moondogs went after Canterbury and busted him open."], ["p", "Robert Fuller made the save before Honky could bring the guitar down. Honky vs. Canterbury has been building since the start of the month. Fuller's role in it is To establish."]], "facts": [["Match", "Mark Canterbury d. Moondog Spot"], ["Result", "DQ, 13:59"], ["Why", "Honky Tonk Man interfered"], ["After", "Canterbury busted open"], ["Save", "Robert Fuller"]], "factTitle": "The Match"}});
Object.assign(ARTICLES, {"uswa-worldwide-renamed-0722": {"p": "uswa", "news": 1, "by": "Newsletter staff", "date": "1991-07-22", "region": "Memphis Report", "kicker": "USWA · Backstage", "factTitle": "The Change", "facts": [["Old name", "USWA Worldwide (13 episodes)"], ["New name", "USWA Mid-South Showcase"], ["First episode", "Evansville, 7/24"], ["Reason", "WCW cease-and-desist"]], "title": "WCW's Lawyers Take Worldwide", "dek": "A cease-and-desist letter from Atlanta forces the USWA to rename its syndicated show. It comes back Wednesday as the Mid-South Showcase.", "body": [["p", "The USWA's syndicated hour has a new name. WCW sent the office a cease-and-desist letter claiming 'Worldwide' as its own, and rather than fight it, the Memphis office changed the title. Starting with the Evansville taping on Wednesday, the show is the USWA Mid-South Showcase."], ["p", "WCW's claim goes back to the Jim Crockett days, when World Wide Wrestling was one of the Charlotte office's two syndicated shows, and Atlanta still runs WorldWide in syndication today. The USWA had been using the name for thirteen episodes, from Jonesboro through Evansville and back to Jonesboro on 7/17."], ["p", "Nothing else changes. Same stations, same Wednesday tapings at Evansville and Jonesboro, same hour. Nobody in Memphis seems to think the letter was really about a TV title. With Ric Flair working Dallas and the Von Erichs drawing in Texas, a USWA show on the same stations as WCW's syndicated hour is something Atlanta would rather not have."]]}});
